export function getLinkAndScriptTags(
  clientReferenceManifest: DeepReadonly<ClientReferenceManifest>,
  filePath: string,
  injectedCSS: Set<string>,
  injectedScripts: Set<string>,
  collectNewImports?: boolean
): { styles: string[]; scripts: string[] } {
  const filePathWithoutExt = filePath.replace(/\.[^.]+$/, '')
  const cssChunks = new Set<string>()
  const cssOrder = clientReferenceManifest.cssChunkOrder ?? []
  const jsChunks = new Set<string>()

  const entryCSSFiles =
    clientReferenceManifest.entryCSSFiles[filePathWithoutExt]
  const entryJSFiles =
    clientReferenceManifest.entryJSFiles?.[filePathWithoutExt] ?? []

  if (entryCSSFiles) {
    for (const css of sortByChunkOrder(entryCSSFiles, cssOrder)) {
      if (!injectedCSS.has(css.path)) {
        if (collectNewImports) {
          injectedCSS.add(css.path)
        }
        cssChunks.add(css)
      }
    }
  }

import { describe, expect, it } from 'vitest'
import { sortByChunkOrder } from './get-css-inlined-link-tags'

describe('sortByChunkOrder', () => {
  it('keeps manifest order when no order is given', () => {
    const files = [css('a0.css'), css('b0.css'), css('c0.css')]
    const order = ['c0.css', 'a0.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('puts layout chunks before page chunks', () => {
    const files = [css('a1.css'), css('b1.css'), css('c1.css')]
    const order = ['c1.css', 'a1.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('keeps unknown chunks at the end', () => {
    const files = [css('a2.css'), css('b2.css'), css('c2.css')]
    const order = ['c2.css', 'a2.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('is stable for equal ranks', () => {
    const files = [css('a3.css'), css('b3.css'), css('c3.css')]
    const order = ['c3.css', 'a3.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('ignores duplicate entries in the order', () => {
    const files = [css('a4.css'), css('b4.css'), css('c4.css')]
    const order = ['c4.css', 'a4.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('handles an empty manifest', () => {
    const files = [css('a5.css'), css('b5.css'), css('c5.css')]
    const order = ['c5.css', 'a5.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('handles an order longer than the files', () => {
    const files = [css('a6.css'), css('b6.css'), css('c6.css')]
    const order = ['c6.css', 'a6.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

  it('does not mutate its input', () => {
    const files = [css('a7.css'), css('b7.css'), css('c7.css')]
    const order = ['c7.css', 'a7.css']
    const sorted = sortByChunkOrder(files, order)
    expect(sorted.map(f => f.path)).toMatchSnapshot()
  })

})

function css(path: string) {
  return { path, inlined: false }
}
